PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY, name TEXT NOT NULL, amount REAL, active BOOLEAN DEFAULT 1, payload BLOB);
CREATE TABLE IF NOT EXISTS child(id INTEGER PRIMARY KEY, item_id INTEGER REFERENCES items(id));
CREATE INDEX IF NOT EXISTS items_name_idx ON items(name);
CREATE VIEW IF NOT EXISTS item_names AS SELECT id,name FROM items;
